const support=load("support"), counts=load("counts"),complete=load("complete");
const stations=Object.keys(support).sort();
function frontier(withdrawn){const feasible=[];for(let start=2000;start<=2019;start++)for(let end=start;end<=2019;end++){
 const cohort=stations.filter(s=>{for(let y=start;y<=end;y++)if(!support[s].includes(y)||(withdrawn&&withdrawn.station===s&&withdrawn.year===y&&counts[s+"|"+y][withdrawn.q-1]===1))return false;return true;});
 if(cohort.length>=2)feasible.push({start,end,duration:end-start+1,cohort});
}return feasible.filter(y=>!feasible.some(x=>x.duration>=y.duration&&x.cohort.length>=y.cohort.length&&(x.duration>y.duration||x.cohort.length>y.cohort.length)));}
const orig=frontier();const trials=[];for(const a of complete){let f=frontier(a);if(JSON.stringify(f)!==JSON.stringify(orig))trials.push({withdrawn:a,frontier:f});}
trials.sort((a,b)=>a.withdrawn.id<b.withdrawn.id?-1:a.withdrawn.id>b.withdrawn.id?1:0);
store("orig",orig);store("trials",trials);
text({original:orig,complete_trials:complete.length,changing_trials:trials.length,total_rows:trials.reduce((s,t)=>s+Math.max(1,t.frontier.length),0),trials:trials.map(t=>({withdrawn:t.withdrawn.id,station:t.withdrawn.station,date:t.withdrawn.date,frontier:t.frontier}))});

const complete=load("complete"),trials=load("trials");const cmp=(a,b)=>a<b?-1:a>b?1:0;
function fixed2(s){let sign=s.startsWith("-")?"-":"";s=s.replace(/^[+-]/,"");let [w,f=""]=s.split(".");w=w||"0";f=f.padEnd(3,"0");let n=BigInt(w)*100n+BigInt(f.slice(0,2));if(Number(f[2])>=5)n++;return sign+(n/100n).toString()+"."+(n%100n).toString().padStart(2,"0");}
const rows=[],events=[];for(const t of trials){const w=t.withdrawn;
for(const f of t.frontier){
const pool=complete.filter(a=>!(a.org===w.org&&a.id===w.id)&&f.cohort.includes(a.station)&&a.year>=f.start&&a.year<=f.end&&a.q===w.q);
pool.sort((a,b)=>Number(a.values["00300"])-Number(b.values["00300"])||cmp(a.date,b.date)||cmp(a.time||"99:99:99",b.time||"99:99:99")||cmp(a.station,b.station)||cmp(a.id,b.id));
const a=pool[0];rows.push([w.org,w.id,w.station,w.date,f.start,f.end,f.cohort.length,f.cohort.join(";"),"Q"+w.q,pool.length,a.org,a.station,a.id,a.date,...["00300","00010","00095","00400"].map(c=>fixed2(a.values[c]))].join("|"));events.push({withdrawn:w.id,start:f.start,end:f.end,n:pool.length,selected:a,tied_oxygen:pool.filter(b=>Number(b.values["00300"])===Number(a.values["00300"])).map(b=>[b.id,b.date,b.time,b.station])});
}}
store("finalrows",rows);store("events",events);text(rows.join("\n"));text(events);

const sql=`WITH usable AS (
 SELECT r.OrganizationIdentifier,r.ActivityIdentifier,a.MonitoringLocationIdentifier,a.ActivityStartDate,a."ActivityStartTime/Time",r.USGSPCode,CAST(r.ResultMeasureValue AS REAL) v
 FROM r JOIN a ON a.OrganizationIdentifier=r.OrganizationIdentifier AND a.ActivityIdentifier=r.ActivityIdentifier AND a.MonitoringLocationIdentifier=r.MonitoringLocationIdentifier AND a.ActivityStartDate=r.ActivityStartDate
 WHERE a.ActivityTypeCode='Sample-Routine' AND a.ActivityMediaName='Water' AND r.ResultStatusIdentifier IN ('Accepted','Final') AND r.ResultValueTypeName='Actual' AND COALESCE(r.ResultDetectionConditionText,'')='' AND COALESCE(r.MeasureQualifierCode,'')=''
 AND ((r.USGSPCode='00010' AND r."ResultMeasure/MeasureUnitCode"='deg C') OR (r.USGSPCode='00095' AND r."ResultMeasure/MeasureUnitCode"='uS/cm @25C') OR (r.USGSPCode='00300' AND r."ResultMeasure/MeasureUnitCode"='mg/l') OR (r.USGSPCode='00400' AND r."ResultMeasure/MeasureUnitCode"='std units'))
), parameters AS (
 SELECT OrganizationIdentifier,ActivityIdentifier,MonitoringLocationIdentifier,ActivityStartDate,"ActivityStartTime/Time",USGSPCode,MIN(v) v,COUNT(DISTINCT v) nv FROM usable GROUP BY 1,2,3,4,5,6
) SELECT OrganizationIdentifier,ActivityIdentifier,MonitoringLocationIdentifier,ActivityStartDate,"ActivityStartTime/Time",CAST(substr(ActivityStartDate,1,4) AS INTEGER) year,1+CAST((CAST(substr(ActivityStartDate,6,2) AS INTEGER)-1)/3 AS INTEGER) quarter,
MAX(CASE WHEN USGSPCode='00010' THEN v END) temperature,MAX(CASE WHEN USGSPCode='00095' THEN v END) conductance,MAX(CASE WHEN USGSPCode='00300' THEN v END) oxygen,MAX(CASE WHEN USGSPCode='00400' THEN v END) pH
FROM parameters GROUP BY 1,2,3,4,5 HAVING COUNT(*)=4 AND MAX(nv)=1`;
