const complete=load("complete"),stations=load("stations").map(r=>r[1]).sort();
function fullState(drop){const quartersets=new Map();for(const a of complete){if(a.id===drop)continue;const k=a.station+"|"+a.year;if(!quartersets.has(k))quartersets.set(k,new Set());quartersets.get(k).add(a.q);}
const windows=[];for(let s=2000;s<=2019;s++)for(let e=s;e<=2019;e++){const cohort=stations.filter(st=>Array.from({length:e-s+1},(_,i)=>quartersets.get(st+"|"+(s+i))?.size===4).every(Boolean));if(cohort.length>=2)windows.push({start:s,end:e,duration:e-s+1,cohort});}
return windows.filter(a=>windows.every(b=>!(b.duration>=a.duration&&b.cohort.length>=a.cohort.length&&(b.duration>a.duration||b.cohort.length>a.cohort.length))));}
const original=JSON.stringify(fullState(null));let verified=[];for(const a of complete){const state=fullState(a.id);if(JSON.stringify(state)!==original)verified.push({id:a.id,frontier:state});}
