) SELECT withdrawn,start_year,end_year,eligible_activity_count,ActivityIdentifier,ActivityStartDate,oxygen,temperature,conductance,pH FROM ranked WHERE rn=1 ORDER BY withdrawn COLLATE BINARY,start_year,end_year`;
